"""Hostile .plasmify bundles, generated by mutating a valid one.

Every bundle must either be refused with a PresetError (never another exception, which would
crash the import dialog) or come out fully validated, with only safely named image files, and
importing it must never write outside the user preset folder.
"""

import contextlib
import io
import os
import random
import stat
import tempfile
import unittest
import zipfile
from pathlib import Path
from unittest import mock

from plasmify import bundle, presets, schema, tomlwrite

PNG = b"\x89PNG\r\n\x1a\n" + b"\x00" * 64
HOSTILE_NAMES = [
    "../evil.png", "/etc/evil.png", "assets/../../evil.png", "assets/..\\..\\evil.png", "assets\\evil.png",
    "assets/evil.png\x00.txt", "assets/" + "a" * 300 + ".png", "assets/evil.png/", "assets/sub/evil.png",
    "assets/.hidden.png", "assets/évil.png", "ASSETS/evil.png", "assets/evil.sh", "preset.toml/evil.png",
    "assets/con.png", "./assets/evil.png",
]  # fmt: skip


def valid_data() -> dict:
    data = presets.find("nord-minimal").data
    data = {k: v for k, v in data.items()}
    data["meta"] = dict(data["meta"], id="fuzzed", name="Fuzzed")
    data["wallpaper"] = {"images": [{"file": "01-mine.png", "credit": "me"}]}
    return data


def make_bundle(entries: list[tuple[str, bytes, int]]) -> bytes:
    """``entries``: (name, content, unix mode or 0)."""
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w", zipfile.ZIP_DEFLATED) as zf:
        for name, content, mode in entries:
            info = zipfile.ZipInfo(name)
            if mode:
                info.external_attr = mode << 16
            zf.writestr(info, content)
    return buffer.getvalue()


def base_entries() -> list[tuple[str, bytes, int]]:
    toml = tomlwrite.dumps(valid_data()).encode()
    return [("preset.toml", toml, 0), ("assets/01-mine.png", PNG, 0)]


class BundleFuzzTests(unittest.TestCase):
    def check(self, raw: bytes, label: str) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            user_dir = root / "home" / "presets"
            path = root / "in.plasmify"
            path.write_bytes(raw)
            before = {p for p in root.rglob("*")}
            with mock.patch.object(bundle, "USER_PRESET_DIR", user_dir):
                try:
                    data, files = bundle.read_bundle(path)
                except presets.PresetError:
                    return
                except Exception as exc:  # noqa: BLE001 (any other exception is the bug)
                    self.fail(f"{label}: {type(exc).__name__}: {exc}")
                self.assertEqual(schema.validate(data), [], label)
                for name, content in files.items():
                    self.assertIsNone(schema.IMAGE_FILE(name), f"{label}: {name!r}")
                    self.assertTrue(content.startswith(b"\x89PNG") or content[:3] == b"\xff\xd8\xff", label)
                with contextlib.suppress(presets.PresetError, FileExistsError):
                    bundle.import_file(path, replace=True)
            for created in {p for p in root.rglob("*")} - before:
                self.assertTrue(
                    created.is_relative_to(user_dir) or created == root / "home",
                    f"{label}: wrote {created} outside the preset folder",
                )

    def test_the_unmutated_bundle_imports(self):
        """Sanity check: the fuzzer starts from a bundle that really works."""
        with tempfile.TemporaryDirectory() as tmp, mock.patch.object(bundle, "USER_PRESET_DIR", Path(tmp, "p")):
            path = Path(tmp, "ok.plasmify")
            path.write_bytes(make_bundle(base_entries()))
            preset = bundle.import_file(path)
            self.assertEqual(preset.id, "fuzzed")
            self.assertTrue((preset.asset_dir / "01-mine.png").read_bytes().startswith(b"\x89PNG"))

    def test_hostile_entry_names(self):
        for name in HOSTILE_NAMES:
            with self.subTest(name=name):
                self.check(make_bundle([*base_entries(), (name, PNG, 0)]), f"name {name!r}")

    def test_symlink_and_device_entries(self):
        for mode in (stat.S_IFLNK | 0o777, stat.S_IFCHR | 0o644, stat.S_IFIFO | 0o644):
            entries = base_entries()
            entries[1] = ("assets/01-mine.png", b"/etc/passwd", mode)
            with self.subTest(mode=oct(mode)):
                self.check(make_bundle(entries), f"mode {oct(mode)}")

    def test_disguised_and_duplicate_files(self):
        cases = {
            "script as png": [base_entries()[0], ("assets/01-mine.png", b"#!/bin/sh\nrm -rf ~\n", 0)],
            "duplicate": [*base_entries(), ("assets/01-mine.png", b"#!/bin/sh\n", 0)],
            "missing image": [base_entries()[0]],
            "no preset": [base_entries()[1]],
            "two presets": [*base_entries(), ("preset.toml", b'schema = 1\n[meta]\nid = "x"\n', 0)],
            "toml bomb": [("preset.toml", b"a = " + b"[" * 50000 + b"]" * 50000, 0), base_entries()[1]],
            "huge string": [("preset.toml", b'x = "' + b"A" * 3_000_000 + b'"', 0), base_entries()[1]],
        }
        for label, entries in cases.items():
            with self.subTest(label):
                self.check(make_bundle(entries), label)

    def test_random_byte_corruption(self):
        rng = random.Random(1337)  # noqa: S311 (test data)
        good = make_bundle(base_entries())
        for round_ in range(300):
            raw = bytearray(good)
            for _ in range(rng.randint(1, 12)):
                raw[rng.randrange(len(raw))] = rng.randrange(256)
            with self.subTest(round=round_):
                self.check(bytes(raw), f"corruption round {round_}")

    def test_truncated_bundles(self):
        good = make_bundle(base_entries())
        for cut in range(0, len(good), max(len(good) // 40, 1)):
            with self.subTest(cut=cut):
                self.check(good[:cut], f"truncated at {cut}")


if __name__ == "__main__":
    os.environ.setdefault("QT_QPA_PLATFORM", "offscreen")
    unittest.main()
